import React, { useEffect, useState } from "react";
import axios from "axios";
import AlertBox from "./AlertBox";

function AssignmentsTeacher() {
  const teacherId = localStorage.getItem("user_id");

  const [courses, setCourses] = useState([]);
  const [alert, setAlert] = useState(null);
  const [formData, setFormData] = useState({
    course_id: "",
    title: "",
    description: "",
    due_date: ""
  });

  useEffect(() => {
    axios.get("http://127.0.0.1:8000/courses")
      .then((res) => {
        const allCourses = res.data.courses || [];
        const myCourses = allCourses.filter(
          (c) => String(c.teacher_id) === String(teacherId)
        );
        setCourses(myCourses);
      })
      .catch((err) => console.error(err));
  }, [teacherId]);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const payload = {
        ...formData,
        course_id: parseInt(formData.course_id),
        teacher_id: parseInt(teacherId)
      };

      const res = await axios.post("http://127.0.0.1:8000/create-assignment", payload);

      setAlert({
        message: res.data.message,
        type: "success"
      });

      setFormData({
        course_id: "",
        title: "",
        description: "",
        due_date: ""
      });
    } catch (err) {
      setAlert({
        message: "Assignment creation failed",
        type: "error"
      });
    }
  };

  return (
    <div>
      {alert && (
        <AlertBox
          message={alert.message}
          type={alert.type}
          onClose={() => setAlert(null)}
        />
      )}

      <h2>Create Assignment</h2>

      <form
        onSubmit={handleSubmit}
        style={{
          display: "grid",
          gap: "12px",
          maxWidth: "500px"
        }}
      >
        <select
          name="course_id"
          value={formData.course_id}
          onChange={handleChange}
        >
          <option value="">Select Course</option>
          {courses.map((course) => (
            <option key={course.id} value={course.id}>
              {course.title}
            </option>
          ))}
        </select>

        <input
          type="text"
          name="title"
          placeholder="Assignment Title"
          value={formData.title}
          onChange={handleChange}
        />

        <input
          type="text"
          name="description"
          placeholder="Description"
          value={formData.description}
          onChange={handleChange}
        />

        <input
          type="date"
          name="due_date"
          value={formData.due_date}
          onChange={handleChange}
        />

        <button type="submit">Create Assignment</button>
      </form>
    </div>
  );
}

export default AssignmentsTeacher;
